posts = [["python", "ai"], ["python", "web"], ["ai"]]
tags = set()
for post_tags in posts:
    for tag in post_tags:
        tags.add(tag)
print(sorted(tags))

monday = set(input("Monday visitors: ").split(","))
tuesday = set(input("Tuesday visitors: ").split(","))
both = monday & tuesday
new = tuesday - monday
print(f"Monday: {len(monday)} unique")
if both:
    print("Both days:", ", ".join(sorted(both)))
else:
    print("Both days: none")
if new:
    print("New on Tuesday:", ", ".join(sorted(new)))
else:
    print("New on Tuesday: none")

orders = []
line = input("Order: ")
while line != "end":
    name, amount = line.split()
    orders.append({"customer": name, "amount": int(amount)})
    line = input("Order: ")

spend = {}
for order in orders:
    name = order["customer"]
    spend[name] = spend.get(name, 0) + order["amount"]
for name in sorted(spend, key=spend.get, reverse=True):
    print(f"{name}: ₹{spend[name]}")
